def get_full_text() -> str:
    """Returns the full text of all pages joined by page breaks."""
    return "\n\n--- Page Break ---\n\n".join(page["text"] for page in PAGES)

def get_page(page_number: int) -> dict:
    """Returns the data dictionary for a specific page (1-indexed)."""
    if 1 <= page_number <= len(PAGES):
        return PAGES[page_number - 1]
    raise IndexError(f"Page number {page_number} out of range (1 to {len(PAGES)})")

